import math


class CompositionalPipeline:
    """Chained normalizer -> discretizer pipeline with global boundary safety.

    The pipeline must stay well defined for extreme out-of-distribution
    coordinates (huge magnitudes, infinities, NaNs), never leaking past the
    valid output range of any stage.
    """

    NUM_BUCKETS = 100

    @staticmethod
    def _to_float(x) -> float:
        """Coerce the input to a finite float, defaulting to -1.0 on failure."""
        try:
            value = float(x)
        except (TypeError, ValueError, OverflowError):
            return -1.0
        if value != value or value in (math.inf, -math.inf):  # NaN / infinity
            return -1.0
        return value

    @staticmethod
    def _clamp(value: float, low: float, high: float) -> float:
        if value != value:  # NaN
            return low
        if value == math.inf:
            return high
        if value == -math.inf:
            return low
        return min(max(value, low), high)

    def normalize(self, x: float) -> float:
        """Map input x to [-1.0, 1.0] using hyperbolic tangent.

        Robust to extreme values: results are always clamped into the closed
        interval so downstream stages observe a valid boundary.
        """
        value = self._to_float(x)
        try:
            norm = math.tanh(value)
        except (OverflowError, ValueError):
            norm = -1.0
        return self._clamp(norm, -1.0, 1.0)

    def discretize(self, x: float) -> int:
        """Map x in [-1.0, 1.0] to a discrete bucket in [0, 99].

        Globally boundary-safe: saturation at +1.0 is folded into the last
        bucket instead of producing an out-of-range index.
        """
        value = self._clamp(self._to_float(x), -1.0, 1.0)
        bucket = int((value + 1.0) / 2.0 * self.NUM_BUCKETS)
        if bucket < 0:
            bucket = 0
        elif bucket >= self.NUM_BUCKETS:
            bucket = self.NUM_BUCKETS - 1
        return bucket

    def compose_pipeline(self, x: float) -> int:
        """Chain normalizer and discretizer with global boundary safety."""
        norm_x = self.normalize(x)
        return self.discretize(norm_x)

