import math


class CompositionalPipeline:
    """Chained Normalizer -> Discretizer pipeline with global boundary safety.

    Each module in isolation obeys its own bounds (tanh stays in [-1, 1], the
    discretizer only accepts [0, 99]).  Composing them naively leaks the
    saturation point of tanh (exactly +/-1.0 for huge inputs) into the
    discretizer, producing bucket 100 and an IndexError.  This wrapper clamps
    the intermediate coordinate so the composition is globally invariant.
    """

    NUM_BUCKETS = 100
    # Half-open bucket range: coordinates in [-1, 1) map to [0, 99].
    _EPS = 1e-16

    def normalize(self, x: float) -> float:
        """Map x to the open interval (-1, 1) using hyperbolic tangent."""
        try:
            x = float(x)
        except (TypeError, ValueError):
            return 0.0
        if math.isnan(x):
            return 0.0
        if math.isinf(x):
            # tanh saturates to exactly +/-1.0 here; preempt the leak.
            return math.copysign(1.0 - self._EPS, x)
        t = math.tanh(x)
        # Guard against numerical saturation (e.g. tanh(1e300) -> 1.0).
        if t >= 1.0:
            t = 1.0 - self._EPS
        elif t <= -1.0:
            t = -1.0 + self._EPS
        return t

    def discretize(self, x: float) -> int:
        """Map a coordinate in [-1, 1] to a discrete bucket in [0, 99]."""
        try:
            x = float(x)
        except (TypeError, ValueError):
            x = 0.0
        if math.isnan(x):
            x = 0.0
        scaled = (x + 1.0) / 2.0 * self.NUM_BUCKETS
        if math.isinf(scaled) or math.isnan(scaled):
            scaled = 0.0
        bucket = int(math.floor(scaled))
        # Global boundary check: never emit an out-of-range bucket.
        if bucket < 0:
            bucket = 0
        elif bucket >= self.NUM_BUCKETS:
            bucket = self.NUM_BUCKETS - 1
        return bucket

    def compose_pipeline(self, x: float) -> int:
        """Normalize then discretize, clamping the intermediate coordinate."""
        norm_x = self.normalize(x)
        # Clamp to [-1 + eps, 1 - eps] so the upper bucket boundary 100 is
        # unreachable even under adversarial out-of-distribution inputs.
        norm_x = min(max(norm_x, -1.0 + self._EPS), 1.0 - self._EPS)
        return self.discretize(norm_x)

