        # and the resulting index is clamped as well, so boundary leaks
        # (values slightly outside [-1, 1], +/-inf or NaN) can never overflow.
        x = self._clamp(x)
        bucket = int((x + 1.0) / 2.0 * self.NUM_BUCKETS)
